INSERT INTO pages (slug, title, body, meta_description, is_published, show_in_footer) VALUES
('about', 'About', '# About\n\nThis community connects people worldwide — and nearby — to ask, answer, and solve real problems together, across technology, business, health, education, lifestyle, and more.\n\nFilter by category, tag, country, or city to find answers relevant to you, or help someone near you directly.', 'Learn about this community platform.', 1, 1),
('privacy', 'Privacy Policy', '# Privacy Policy\n\nWe collect the information you provide when you register (username, email) and content you post (questions, answers, comments, optional location). We use this data to operate the community, personalize "near me" filtering, and send account-related email. We do not sell your personal data. Contact us with any privacy requests.', 'How we collect and use your data.', 1, 1),
('terms', 'Terms of Service', '# Terms of Service\n\nBy using this site you agree to post respectful, on-topic content, not to spam or abuse other members, and that content you post may be publicly visible and indexed by search engines. We may remove content or accounts that violate these terms.', 'Terms and conditions of use.', 1, 1),
('cookies', 'Cookie Policy', '# Cookie Policy\n\nWe use essential cookies to keep you signed in and remember your session. We do not use third-party advertising or tracking cookies at this time. Disabling cookies in your browser will prevent you from logging in.', 'How we use cookies.', 1, 1),
('guidelines', 'Community Guidelines', '# Community Guidelines\n\n- Be respectful — no harassment, hate speech, or personal attacks.\n- Stay on topic and search before posting a duplicate question.\n- No spam, self-promotion, or unrelated links.\n- Give credit when sharing others'' work.\n- Report content that violates these guidelines instead of engaging.', 'Rules for participating in the community.', 1, 1);
